const metrics: Record<string, Description> = {
  SNR_METRIC: {
    en: ["Measures waveform fidelity as the ratio of original signal energy to error energy.", "Computes 10 log10 of reference energy divided by the energy of the samplewise difference. Higher dB means less error relative to the reference. Requires aligned signals and penalises gain or time shifts strongly. It measures numerical fidelity, not perceived quality, message recovery or steganographic detectability."],
    pl: ["Mierzy wierność przebiegu jako stosunek energii oryginału do energii błędu.", "Oblicza 10 log10 ilorazu energii odniesienia i energii różnicy próbek. Więcej dB oznacza mniejszy błąd względem oryginału. Wymaga wyrównanych sygnałów i silnie karze zmianę wzmocnienia lub przesunięcie. Mierzy zgodność liczbową, a nie jakość słuchową, odczyt wiadomości czy wykrywalność steganografii."],
  },
  SNR_SEG_METRIC: {
    en: ["Averages signal-to-noise ratios over short speech frames.", "Calculates a local energy-to-error ratio for each frame, limits extreme frame scores and averages them. This gives quieter sections more influence than a single global SNR. Higher dB is better. Frame length, silence and alignment affect the result; it remains an error-energy measure rather than a listening score."],
    pl: ["Uśrednia stosunek sygnału do szumu w krótkich ramkach mowy.", "Oblicza lokalny stosunek energii sygnału do błędu, ogranicza skrajne wyniki ramek i uśrednia je. Cichsze fragmenty mają większy wpływ niż w globalnym SNR. Więcej dB oznacza lepszy wynik. Długość ramek, cisza i wyrównanie wpływają na ocenę; nadal jest to miara energii błędu, a nie ocena odsłuchowa."],
  },
  FWSNR_SEG_METRIC: {
    en: ["Measures segmental SNR with frequency-band weighting relevant to speech.", "Separates short-time spectra into perceptual bands, computes bandwise signal-to-error ratios and combines them with frequency-dependent weights. Higher scores indicate less weighted distortion. It can distinguish errors with similar total energy but different spectral locations; it requires a reference and temporal alignment."],
    pl: ["Mierzy segmentowy SNR z ważeniem pasm częstotliwości istotnych dla mowy.", "Rozdziela widma krótkoczasowe na pasma percepcyjne, oblicza stosunki sygnału do błędu w pasmach i łączy je wagami częstotliwościowymi. Wyższy wynik oznacza mniejsze ważone zniekształcenie. Rozróżnia błędy o podobnej energii, lecz innym położeniu widmowym; wymaga oryginału i wyrównania czasowego."],
  },
  PESQ_METRIC: {
    en: ["Predicts perceived speech quality by comparing degraded speech with its reference.", "Uses the PESQ perceptual model to align and compare auditory representations, combining disturbance measures into MOS-LQO. Higher is better; the catalogue reports the wideband scale up to about 4.64. The implementation depends on the PESQ library and supported speech sample rates. It is a speech-quality estimate, not a general music metric or a bit-error measure."],
    pl: ["Przewiduje postrzeganą jakość mowy przez porównanie zniekształconego sygnału z oryginałem.", "Model percepcyjny PESQ wyrównuje i porównuje reprezentacje słuchowe, łącząc miary zakłóceń w MOS-LQO. Wyższy wynik jest lepszy; katalog podaje skalę szerokopasmową do około 4,64. Implementacja zależy od biblioteki PESQ i obsługiwanych częstotliwości mowy. To estymacja jakości mowy, a nie ogólna miara muzyki ani błędów bitowych."],
  },
  VISQOL_METRIC: {
    en: ["Estimates perceived audio quality from similarity between reference and processed spectrograms.", "Uses official Google ViSQOL bindings and the audio-mode SVR model, with both inputs polyphase-resampled to 48 kHz. Spectro-temporal similarity is mapped to MOS-LQO, whose audio-model maximum is about 4.75. Prefer active clips around 8–10 seconds. Requires optional bindings and model data; do not compare these scores directly with ViSQOL speech mode."],
    pl: ["Szacuje postrzeganą jakość dźwięku z podobieństwa spektrogramów oryginału i sygnału przetworzonego.", "Używa oficjalnych wiązań Google ViSQOL i modelu SVR trybu audio; oba wejścia są przeliczane wielofazowo do 48 kHz. Podobieństwo czasowo-widmowe jest mapowane na MOS-LQO z maksimum modelu audio około 4,75. Preferowane są aktywne fragmenty około 8–10 sekund. Wymaga opcjonalnych wiązań i modelu; wyników nie należy bezpośrednio porównywać z trybem speech."],
  },
  LSD_METRIC: {
    en: ["Measures the difference between short-time log-magnitude spectra in decibels.", "Uses 32 ms Hann windows with 75% overlap and a −100 dBFS magnitude floor. For each frame it takes the RMS spectral difference in dB, then averages frames. Lower is closer to the reference. It exposes spectral changes but ignores phase differences that leave magnitudes unchanged; it is a diagnostic, not a MOS predictor."],
    pl: ["Mierzy różnicę krótkoczasowych logarytmicznych widm amplitudowych w decybelach.", "Używa okien Hanna 32 ms z nakładaniem 75% i dolnym ograniczeniem modułu −100 dBFS. Dla ramki liczy RMS różnic widma w dB, a następnie uśrednia ramki. Mniej oznacza większą zgodność z oryginałem. Ujawnia zmiany widmowe, ale pomija zmiany fazy bez zmiany modułu; to diagnostyka, nie predykcja MOS."],
  },
  MRSC_METRIC: {
    en: ["Measures relative spectral error at several time-frequency resolutions.", "Computes STFT magnitudes with 16, 32 and 64 ms windows and 75% overlap. At each resolution it divides the Frobenius norm of the magnitude error by the reference norm, then averages. Lower is better and zero indicates matching magnitudes. A silent reference is undefined; some phase changes remain invisible. This ratio is not a perceptual MOS."],
    pl: ["Mierzy względny błąd widma w kilku rozdzielczościach czasowo-częstotliwościowych.", "Liczy moduły STFT z oknami 16, 32 i 64 ms oraz nakładaniem 75%. Dla każdej rozdzielczości dzieli normę Frobeniusa błędu modułu przez normę oryginału i uśrednia wyniki. Mniej jest lepiej, a zero oznacza zgodne moduły. Dla cichego odniesienia wynik jest nieokreślony; część zmian fazy pozostaje niewidoczna. Ten iloraz nie jest percepcyjnym MOS."],
  },
  WSS_METRIC: {
    en: ["Compares the slopes of reference and processed speech spectra.", "Calculates differences between adjacent perceptual-band levels and weights slope mismatches, emphasising important spectral peaks. Lower distance means better preservation of spectral shape. Requires reference speech and aligned frames. It highlights spectral-envelope damage but does not directly measure intelligibility or payload recovery."],
    pl: ["Porównuje nachylenia widm oryginalnej i przetworzonej mowy.", "Oblicza różnice poziomów sąsiednich pasm percepcyjnych i waży niezgodność nachyleń, podkreślając istotne szczyty widma. Mniejsza odległość oznacza lepsze zachowanie kształtu widma. Wymaga mowy odniesienia i wyrównanych ramek. Ujawnia zmiany obwiedni widmowej, ale nie mierzy bezpośrednio zrozumiałości ani odczytu danych."],
  },
  LLR_METRIC: {
    en: ["Measures how much the linear-prediction model of speech changes after processing.", "Fits linear predictive coefficients to reference and processed frames, then evaluates a log ratio of prediction-error terms using the reference autocorrelation. Lower values indicate more similar spectral envelopes. It is intended for speech; silence, numerical conditioning and time alignment can affect the estimate."],
    pl: ["Mierzy zmianę modelu predykcji liniowej mowy po przetworzeniu.", "Dopasowuje współczynniki predykcji liniowej do ramek oryginału i wyniku, po czym oblicza logarytm ilorazu składników błędu z autokorelacją odniesienia. Niższa wartość oznacza bardziej podobne obwiednie widmowe. Miara jest przeznaczona do mowy; cisza, uwarunkowanie numeryczne i wyrównanie czasowe wpływają na estymację."],
  },
  CEPSTRUM_DISTANCE_METRIC: {
    en: ["Compares cepstral representations of reference and processed speech.", "Derives cepstral coefficients from short-frame speech models and computes their distance. Cepstral features describe spectral-envelope shape rather than individual waveform samples. Lower distance in dB means a closer envelope. It needs a reference and should be interpreted alongside other metrics, since matching envelopes do not imply identical phase or perceptual quality."],
    pl: ["Porównuje reprezentacje cepstralne oryginalnej i przetworzonej mowy.", "Wyznacza współczynniki cepstralne z modeli krótkich ramek mowy i oblicza ich odległość. Cechy cepstralne opisują obwiednię widma zamiast pojedynczych próbek. Mniejsza odległość w dB oznacza bliższą obwiednię. Wymaga odniesienia i interpretacji z innymi metrykami, bo podobne obwiednie nie gwarantują zgodnej fazy ani jakości słuchowej."],
  },
  MEL_CEPSTRAL_DISTANCE_METRIC: {
    en: ["Measures changes in speech spectral shape using a mel-scaled representation.", "Builds 20-band mel power spectrograms with a 1024-sample Hamming window and 256-sample hop, then passes them to the mel-cepstral-distance comparison library. Lower MCD means closer representations. Values depend on feature extraction and comparison settings, so scores from differently configured MCD implementations are not automatically interchangeable."],
    pl: ["Mierzy zmiany kształtu widma mowy w reprezentacji o skali melowej.", "Buduje 20-pasmowe melowe spektrogramy mocy z oknem Hamminga 1024 próbki i krokiem 256, a następnie przekazuje je do biblioteki mel-cepstral-distance. Niższe MCD oznacza bliższe reprezentacje. Wyniki zależą od ekstrakcji cech i ustawień porównania, więc wartości z różnych konfiguracji MCD nie są automatycznie porównywalne."],
  },
  SISDR_METRIC: {
    en: ["Measures waveform distortion after compensating for a single global scale factor.", "Projects the processed signal onto the reference and compares projected target energy with residual energy in dB. Higher SI-SDR is better. Unlike ordinary SNR, a uniform gain change is discounted; timing errors and other waveform changes still count. Use alongside level-sensitive metrics when amplitude preservation matters."],
    pl: ["Mierzy zniekształcenie przebiegu po kompensacji jednego globalnego współczynnika skali.", "Rzutuje sygnał przetworzony na oryginał i porównuje energię projekcji z energią reszty w dB. Wyższy SI-SDR jest lepszy. W odróżnieniu od zwykłego SNR pomija jednolite wzmocnienie; błędy czasu i inne zmiany przebiegu nadal wpływają na wynik. Jeśli ważne jest zachowanie amplitudy, warto zestawić go z miarą czułą na poziom."],
  },
  BSS_EVAL_METRIC: {
    en: ["Reports several distortion measures originally designed for source-separation evaluation.", "Uses museval BSS Eval v4 to decompose estimation errors into target-related, interference and artefact terms. Returns SDR, ISR, SIR and SAR in dB, plus a source permutation index. Higher is better for the four ratios; perm identifies source assignment and is not a quality score. Some components can be degenerate for single-source comparisons."],
    pl: ["Zwraca kilka miar zniekształceń opracowanych do oceny separacji źródeł.", "Używa museval BSS Eval v4 do rozłożenia błędów estymacji na składniki związane z celem, interferencją i artefaktami. Zwraca SDR, ISR, SIR i SAR w dB oraz indeks permutacji źródeł. Więcej jest lepiej dla czterech ilorazów; perm określa przypisanie źródła i nie jest oceną jakości. Przy porównaniu jednego źródła część składników może być zdegenerowana."],
  },
  CBAK_METRIC: {
    en: ["Predicts the perceived intrusiveness of background noise in processed speech.", "Combines PESQ, segmental SNR and weighted spectral slope through an empirical regression. The resulting composite score is limited to the 1–5 range, with higher values meaning less intrusive background noise. It is calibrated for speech enhancement and needs the original reference; it is not a direct measurement of background-noise power."],
    pl: ["Przewiduje dokuczliwość szumu tła w przetworzonej mowie.", "Łączy PESQ, segmentowy SNR i ważone nachylenie widma przez regresję empiryczną. Wynik złożony jest ograniczany do zakresu 1–5; więcej oznacza mniej dokuczliwe tło. Model skalibrowano dla poprawy jakości mowy i wymaga on oryginału; nie jest bezpośrednim pomiarem mocy szumu."],
  },
  CSIG_METRIC: {
    en: ["Predicts how much the speech signal itself sounds distorted.", "Combines PESQ, log-likelihood ratio and weighted spectral slope using an empirical regression, then limits the prediction to 1–5. Higher values mean better predicted speech-signal quality. It focuses on speech distortion rather than background-noise annoyance and is a model estimate, not a listener’s actual rating."],
    pl: ["Przewiduje, jak silnie zniekształcony brzmi sam sygnał mowy.", "Łączy PESQ, logarytmiczny iloraz wiarygodności i ważone nachylenie widma przez regresję empiryczną, po czym ogranicza wynik do 1–5. Więcej oznacza lepszą przewidywaną jakość samej mowy. Skupia się na zniekształceniu mowy, a nie dokuczliwości tła; jest estymacją modelu, nie rzeczywistą oceną słuchacza."],
  },
  COVL_METRIC: {
    en: ["Predicts overall speech quality, combining signal distortion and noise effects.", "Uses an empirical combination of PESQ, log-likelihood ratio and weighted spectral slope to produce a composite 1–5 score. Higher is better. The model was designed for speech-enhancement evaluation; its scale should not be treated as directly interchangeable with PESQ, MOSNet or a listening-test MOS."],
    pl: ["Przewiduje ogólną jakość mowy, łącząc wpływ zniekształcenia sygnału i szumu.", "Używa empirycznego połączenia PESQ, logarytmicznego ilorazu wiarygodności i ważonego nachylenia widma, tworząc ocenę 1–5. Więcej jest lepiej. Model służy ocenie poprawy jakości mowy; jego skali nie należy utożsamiać bezpośrednio z PESQ, MOSNet ani MOS z testu odsłuchowego."],
  },
  STOI_METRIC: {
    en: ["Estimates speech intelligibility from preservation of short-time spectral envelopes.", "Compares reference and processed temporal envelopes in one-third-octave bands over short segments, after the algorithm’s normalisation and clipping steps. Higher values, commonly near the 0–1 range, suggest better intelligibility. It does not recognise words: the score is not a percentage of correctly understood words and is not a general music-quality metric."],
    pl: ["Szacuje zrozumiałość mowy na podstawie zachowania krótkoczasowych obwiedni widmowych.", "Porównuje obwiednie czasowe oryginału i wyniku w pasmach tercjowych oraz krótkich segmentach, po normalizacji i ograniczaniu przewidzianym w algorytmie. Wyższy wynik, zwykle w pobliżu zakresu 0–1, sugeruje lepszą zrozumiałość. Nie rozpoznaje słów: wynik nie jest procentem zrozumianych wyrazów ani ogólną miarą jakości muzyki."],
  },
  ESTOI_METRIC: {
    en: ["Extends STOI with a spectro-temporal comparison useful for fluctuating interference.", "Uses pystoi in extended mode, comparing normalised short-time time-frequency envelope patterns. Higher eSTOI indicates better predicted speech intelligibility, usually on an index scale near 0–1. It requires reference speech and remains a proxy: it does not measure listening quality, message decoding or steganographic security."],
    pl: ["Rozszerza STOI o porównanie czasowo-widmowe przydatne dla zmiennych zakłóceń.", "Korzysta z rozszerzonego trybu pystoi i porównuje znormalizowane krótkoczasowe wzorce obwiedni czasowo-częstotliwościowych. Wyższe eSTOI oznacza lepszą przewidywaną zrozumiałość mowy, zwykle w skali bliskiej 0–1. Wymaga mowy odniesienia i pozostaje wskaźnikiem zastępczym: nie mierzy jakości odsłuchu, odczytu danych ani bezpieczeństwa steganografii."],
  },
  CSII_METRIC: {
    en: ["Estimates intelligibility using coherence between reference and processed speech.", "Computes coherence-based signal-to-distortion information in weighted frequency bands. Returns separate high, mid and low indices for speech segments at different levels. Higher values indicate better preserved intelligibility cues. The three components describe different portions of speech and should not be mistaken for repeated measurements of one global score."],
    pl: ["Szacuje zrozumiałość z koherencji oryginalnej i przetworzonej mowy.", "Oblicza informację o stosunku sygnału do zniekształceń na podstawie koherencji w ważonych pasmach. Zwraca osobne indeksy high, mid i low dla segmentów mowy o różnych poziomach. Wyższe wartości oznaczają lepiej zachowane wskazówki zrozumiałości. Trzy składowe opisują różne części mowy, a nie powtórzenia jednego wyniku globalnego."],
  },
  NCM_METRIC: {
    en: ["Measures preservation of slow speech-envelope modulations across frequency bands.", "Splits speech into 20 bands, extracts Hilbert envelopes and resamples them to 32 Hz. Normalised envelope covariance is mapped to apparent SNR and combined using speech-importance weights. Higher scores indicate better predicted intelligibility. This implementation accepts 8 or 16 kHz input and requires a reference; it does not assess bit recovery."],
    pl: ["Mierzy zachowanie wolnych modulacji obwiedni mowy w pasmach częstotliwości.", "Dzieli mowę na 20 pasm, wyznacza obwiednie Hilberta i przelicza je do 32 Hz. Znormalizowana kowariancja obwiedni jest mapowana na pozorny SNR i łączona wagami ważności pasm mowy. Wyższy wynik oznacza lepszą przewidywaną zrozumiałość. Ta implementacja przyjmuje wejście 8 lub 16 kHz i wymaga oryginału; nie ocenia odczytu bitów."],
  },
  STGI_METRIC: {
    en: ["Estimates how many local spectro-temporal speech patterns remain sufficiently preserved.", "Resamples speech to 10 kHz, builds log-mel spectrograms and applies spectro-temporal Gabor filters. Normalised local similarities are compared with channel-specific thresholds; the score averages the resulting preserved-pattern decisions. Higher is better on a 0–1 scale. Sufficient speech duration is needed for the analysis windows; the result is not a word-recognition rate."],
    pl: ["Szacuje, ile lokalnych wzorców czasowo-widmowych mowy zachowało wystarczającą zgodność.", "Przelicza mowę do 10 kHz, buduje logarytmiczne spektrogramy melowe i stosuje czasowo-widmowe filtry Gabora. Znormalizowane podobieństwa lokalne są porównywane z progami kanałów, a wynik uśrednia decyzje o zachowaniu wzorców. Więcej jest lepiej w skali 0–1. Potrzebna jest długość mowy wystarczająca dla okien analizy; to nie odsetek rozpoznanych słów."],
  },
  WSTMI_METRIC: {
    en: ["Predicts intelligibility from weighted spectro-temporal modulation similarities.", "Computes log-mel features and Gabor modulation responses after conversion to 10 kHz. Normalised reference-to-processed correlations are combined with fixed learned weights and a bias. Higher values indicate better predicted intelligibility. This is an index, not a percentage or MOS; interpret it consistently within the same implementation and speech domain."],
    pl: ["Przewiduje zrozumiałość z ważonych podobieństw modulacji czasowo-widmowych.", "Po konwersji do 10 kHz oblicza cechy log-mel i odpowiedzi filtrów modulacyjnych Gabora. Znormalizowane korelacje oryginału z wynikiem łączy stałymi wyuczonymi wagami i wyrazem wolnym. Wyższa wartość oznacza lepszą przewidywaną zrozumiałość. To indeks, a nie procent ani MOS; należy porównywać go w tej samej implementacji i domenie mowy."],
  },
  SRMR_METRIC: {
    en: ["Estimates reverberation-related degradation from the processed signal alone.", "Analyses modulation energy in auditory-band envelopes and forms a ratio of lower to higher modulation-frequency energy. Higher SRMR generally suggests less reverberant degradation for speech. It does not require a clean reference and is not a direct RT60 estimate. Noise, speaking style and signal content can also influence its value."],
    pl: ["Szacuje degradację związaną z pogłosem na podstawie samego sygnału przetworzonego.", "Analizuje energię modulacji obwiedni w pasmach słuchowych i tworzy stosunek energii niższych do wyższych częstotliwości modulacji. Wyższe SRMR zwykle sugeruje mniejszą degradację pogłosową mowy. Nie wymaga czystego oryginału i nie jest bezpośrednią estymacją RT60. Na wynik wpływają też szum, sposób mówienia i treść sygnału."],
  },
  BSD_METRIC: {
    en: ["Measures reference-relative spectral distortion on the Bark auditory scale.", "Maps short-time power spectra into 32 Bark bands and averages the squared band-energy error normalised by reference band energy. Lower values mean closer spectra. Although grouped with reverberation metrics, it responds to other spectral changes as well and is not a direct measurement of room reverberation time."],
    pl: ["Mierzy zniekształcenie widmowe względem oryginału w słuchowej skali Bark.", "Mapuje krótkoczasowe widma mocy do 32 pasm Bark i uśrednia kwadrat błędu energii pasm normalizowany energią odniesienia. Niższy wynik oznacza bliższe widma. Choć znajduje się w grupie metryk pogłosu, reaguje także na inne zmiany widmowe i nie mierzy bezpośrednio czasu pogłosu pomieszczenia."],
  },
  AI_MOSNET_METRIC: {
    en: ["Predicts speech quality using a pretrained neural network rather than a samplewise reference comparison.", "Feeds magnitude spectrograms through convolutional and bidirectional LSTM layers and averages frame predictions. TAF evaluates cover and processed audio independently, returning both scores; only processed is ranked as the result. Higher predicts better quality. Requires TensorFlow and model weights; predictions depend on the training domain and are not actual listener ratings."],
    pl: ["Przewiduje jakość mowy wytrenowaną siecią neuronową zamiast porównywać próbki z oryginałem.", "Przekazuje spektrogramy amplitudowe przez warstwy konwolucyjne i dwukierunkowe LSTM, po czym uśrednia predykcje ramek. TAF ocenia oryginał i wynik niezależnie, zwracając oba wyniki; tylko processed podlega rankingowi jako rezultat. Więcej oznacza lepszą przewidywaną jakość. Wymaga TensorFlow i wag; oceny zależą od danych treningowych i nie są rzeczywistymi ocenami słuchaczy."],
  },
};

export const catalogueDescriptions = { methods, attacks, metrics };

export function catalogueDescription(kind: CatalogueKind, name: string, locale: Locale) {
  return catalogueDescriptions[kind][name]?.[locale];
}
